// The game's real request bodies (generated by tools/make_backend_fixtures.gd)
// must pass the Worker's input validation. Guards the GDScript <-> TS contract.
import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import { LetterRequest, NewspaperRequest } from "../src/schemas";

const load = (name: string) => JSON.parse(readFileSync(new URL(`./fixtures/${name}`, import.meta.url), "utf8"));

describe("game payload contract", () => {
  it("newspaper request from the game is valid", () => {
    const r = NewspaperRequest.safeParse(load("newspaper_request.json"));
    expect(r.success ? "ok" : JSON.stringify(r.error.issues)).toBe("ok");
  });

  it("letter request from the game is valid", () => {
    const r = LetterRequest.safeParse(load("letter_request.json"));
    expect(r.success ? "ok" : JSON.stringify(r.error.issues)).toBe("ok");
  });
});
